import { readFileSync } from "node:fs";
import { afterEach, describe, expect, it, vi } from "vitest";
import { CsmMessagingProvider } from "./messaging-provider.js";

// Explicit paired-repository integration: fixtures must be freshly generated by
// the real Messaging Phoenix router/controller test, never handwritten responses.
const fixturePath = process.env.COP_LOOKUP_ROUTER_FIXTURE;
type RouterResult = {status: number; body: unknown};
type RouterCases = {managedReady: RouterResult; managedPending: RouterResult; success: RouterResult; partial: RouterResult; notFound: RouterResult; forbidden: RouterResult};
const actor = (subjectId = "lab") => ({subjectId, displayName:"Synthetic", username:"synthetic", roles:[], authMode:"oidc" as const, issuer:"https://lookup.test/realms/cop"});
const now = new Date("2026-11-09T17:00:00Z");
const provider = () => new CsmMessagingProvider({baseUrl:"http://isolated-messaging.test", enabled:true, cacheTtlMs:1000, timeoutMs:1000, token:"synthetic-only"});

describe.skipIf(!fixturePath)("actual Messaging router to COP lookup contract", () => {
  const fixtures = fixturePath ? JSON.parse(readFileSync(fixturePath,"utf8")) as RouterCases : undefined;
  afterEach(() => vi.unstubAllGlobals());
  const use = (value: RouterResult) => {
    const transport = vi.fn(async () => new Response(JSON.stringify(value.body),{status:value.status}));
    vi.stubGlobal("fetch",transport);return transport;
  };
  it("accepts actual router success and adds only the COP short validity", async () => {
    const transport = use(fixtures!.success);
    const result = await provider().lookupMatrixIdentities(actor(),now,"room-1");
    expect(result.statusCode).toBe(200);
    expect(result.body).toMatchObject({actorUserId:"lab",conversationId:"room-1",validUntil:"2026-11-09T17:00:30.000Z",identities:[{userId:"lab",matrixUserId:"@cop_lab:matrix.test"},{userId:"peer",matrixUserId:"@cop_peer:matrix.test"}]});
    expect(transport).toHaveBeenCalledTimes(1);
    expect((transport.mock.calls[0] as unknown as [URL])[0].pathname).toBe("/api/v1/matrix/identities/lookup");
  });
  it("retains actual unprovisioned identity as unresolved without calling resolve", async () => {
    const transport=use(fixtures!.partial);
    expect((await provider().lookupMatrixIdentities(actor(),now,"room-1")).body?.unresolvedUserIds).toEqual(["peer"]);
    expect(transport).toHaveBeenCalledTimes(1);
  });
  it("accepts actual ready vehicle pairs but refuses pending membership cutover", async () => {
    const id = "conv_vehicle_00000000-0000-4000-8000-000000000001";
    use(fixtures!.managedReady);
    expect((await provider().lookupMatrixIdentities(actor(),now,id)).body).toMatchObject({conversationId:id,matrixRoomId:"!room:matrix.test",status:"online"});
    use(fixtures!.managedPending);
    expect((await provider().lookupMatrixIdentities(actor(),now,id)).statusCode).toBe(503);
  });
  it("recognizes only actual context-bound403 and404", async () => {
    use(fixtures!.notFound);
    expect((await provider().lookupMatrixIdentities(actor(),now,"missing")).statusCode).toBe(404);
    use(fixtures!.forbidden);
    expect((await provider().lookupMatrixIdentities(actor("outsider"),now,"room-1")).statusCode).toBe(403);
    use(fixtures!.forbidden);
    expect((await provider().lookupMatrixIdentities(actor(),now,"room-1")).statusCode).toBe(503);
  });
  it("does not mistake the deployed-baseline missing provider route for missing identity", async () => {
    const transport=use({status:404,body:{errors:{detail:"Not Found"}}});
    expect((await provider().lookupMatrixIdentities(actor(),now,"room-1")).statusCode).toBe(503);
    expect(transport).toHaveBeenCalledTimes(1);
  });
});
